//! 🎟️ Encoder action work retains its original loan, actual effect and paid close.
use super::*;
use crate::native_encoding::{NativeEncodeAllocation,NativeEncodeProgress};
use crate::retirement::controlled::ControlledRetirement;
struct Loan(u64);
impl NativeEncodeWorkRecipient for Loan{fn admits(&mut self,observed:u64,additional:u64)->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|sum|sum<=self.0))}fn committed(&mut self,_actual:u64)->Result<(),ValueError>{Ok(())}}
fn close<T:crate::retirement::RetireOwned>(value:T,grant:crate::RetainedCloneGrant){
 let mut owner=ControlledRetirement::new(value).ok().unwrap();
 for _ in 0..4096{if owner.terminal_is_empty(){break}let(result,(born,released))=crate::observe_retirement_allocations(||owner.step(grant));let progress=result.unwrap().progress();assert_eq!((born,released),(progress.retained_capacity_bytes,progress.released_bytes));}
 assert!(owner.terminal_is_empty());
}
#[test]
fn original_encoder_append_reports_only_actual_effects(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🎟️action-work.json")).unwrap();
 let grant:crate::RetainedCloneGrant=serde_json::from_value(f["close"].clone()).unwrap();
 for case in f["cases"].as_array().unwrap(){
  let accepted=case["observerAccepted"].as_bool().unwrap();let allocation_accepted=case["allocationAccepted"].as_bool().unwrap();let source=case["source"].as_str().unwrap();let mut output=Vec::new();
  let mut observer=|event:NativeEncodeProgress|accepted||event.completed==0;
  let mut allocation=|event:crate::native_encoding::NativeEncodeAllocationEvent|if !matches!(event,crate::native_encoding::NativeEncodeAllocationEvent::Quote(_))||allocation_accepted{Ok(())}else{Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture original allocation refused"))};
  let mut allocation_loan_issuer=crate::native_encoding::NativeEncodeAllocationIssuer::new();let mut allocation_loan=allocation_loan_issuer.loan(&mut allocation);let mut native=NativeEncodeControl::new_forwarded(65536,&mut observer,&mut allocation_loan);let mut recipient=Loan(case["allowance"].as_u64().unwrap());let mut issuer=NativeEncodeWorkIssuer::new();let mut loan=issuer.loan(&mut recipient);
  let(result,(born,released))=crate::observe_retirement_allocations(||native.with_work_recipient(&mut loan,|native|{
   let mut child=|_|true;native.scoped_observer(&mut child,|native|native.append_bytes(&mut output,source.as_bytes()))
  }));
  let kind=match result{Ok(())=>"success",Err(error)=>{let kind=error.kind.as_str();close(error,grant);kind}};
  assert_eq!(serde_json::json!({"output":std::str::from_utf8(&output).unwrap(),"work":native.actual_work(),"kind":kind}),case["expected"]);
  assert_eq!((born,released),(output.capacity(),0));
  drop(native);close(output,grant);
 }
}
#[test]
fn scoped_encoder_unwind_returns_same_actual_work(){
 let mut observer=|_|true;let mut native=NativeEncodeControl::new(4096,&mut observer);let mut recipient=Loan(1);let mut issuer=NativeEncodeWorkIssuer::new();let mut loan=issuer.loan(&mut recipient);let mut output=Vec::new();
 let result:Result<Result<(),ValueError>,_>=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.with_work_recipient(&mut loan,|native|{
  let mut child=|_|true;native.scoped_observer(&mut child,|native|{native.append_bytes(&mut output,b"x")?;panic!("fixture unwind after actual append")})
 })));
 assert!(result.is_err());assert_eq!(native.actual_work(),1);assert_eq!(output,b"x");
 let receipt=native.pause().unwrap();assert_eq!(receipt.actual_work(),1);let mut observer=|_|true;let native=NativeEncodeControl::resume(receipt,&mut observer).unwrap();assert_eq!(native.actual_work(),1);drop(native);
 let grant=crate::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};close(output,grant);
}

#[test]
fn issuer_identity_survives_short_loans_and_rejects_a_different_source(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧪️tests/🧫️fixtures/🎟️issuer.json")).unwrap();let mut issuer=NativeEncodeWorkIssuer::new();let mut other=NativeEncodeWorkIssuer::new();let mut recipient=Loan(fixture["allowance"].as_u64().unwrap());let mut callback=|_|true;let mut native=NativeEncodeControl::new(1024,&mut callback);
 let first={let mut loan=issuer.loan(&mut recipient);native.with_work_recipient(&mut loan,|native|Ok::<_,ValueError>(native.work_recipient_identity().unwrap())).unwrap()};
 let second={let mut loan=issuer.loan(&mut recipient);native.with_work_recipient(&mut loan,|native|Ok::<_,ValueError>(native.work_recipient_identity().unwrap())).unwrap()};
 let different={let mut loan=other.loan(&mut recipient);native.with_work_recipient(&mut loan,|native|Ok::<_,ValueError>(native.work_recipient_identity().unwrap())).unwrap()};assert_eq!(first,second);assert_ne!(first,different);
}

