#[test]
fn original_effect_post_unwind_is_reconciled_without_replaying(){
 use crate::native_encoding::{NativeEncodeConstructionIssuer,NativeEncodeConstructionRecipient,NativeEncodeEffectSettlement,NativeEncodeEffectPostPhase};
 use std::cell::Cell;
 struct Work<'a>{calls:&'a Cell<u64>,panic:bool}impl NativeEncodeWorkRecipient for Work<'_>{fn admits(&mut self,_:u64,_:u64)->Result<bool,ValueError>{Ok(true)}fn committed(&mut self,_:u64)->Result<(),ValueError>{self.calls.set(self.calls.get()+1);if self.panic{panic!("original work post")};Ok(())}}
 struct Physical<'a>{calls:&'a Cell<u64>,panic:bool,grant:crate::RetainedCloneGrant}impl NativeEncodeConstructionRecipient for Physical<'_>{fn submitted(&self)->crate::RetainedCloneProgress{Default::default()}fn grant(&mut self,_:crate::RetirementDemand)->Result<crate::RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,_:crate::RetainedCloneGrant,_:crate::RetainedCloneProgress)->Result<(),ValueError>{self.calls.set(self.calls.get()+1);if self.panic{panic!("original physical post")};Ok(())}}
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️settlement.json")).unwrap();for case in f["cases"].as_array().unwrap(){let work_calls=Cell::new(0);let physical_calls=Cell::new(0);let panic=case["panic"].as_str().unwrap();let grant=crate::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut work=Work{calls:&work_calls,panic:panic=="work"};let mut physical=Physical{calls:&physical_calls,panic:panic=="physical",grant};let mut work_issuer=NativeEncodeWorkIssuer::new();let mut physical_issuer=NativeEncodeConstructionIssuer::new();let mut work_loan=work_issuer.loan(&mut work);let mut physical_loan=physical_issuer.loan(&mut physical);let mut callback=|_|true;let mut native=NativeEncodeControl::new(0,&mut callback);let mut settlement=None;
 native.with_construction_recipient(&mut physical_loan,|native|native.with_work_recipient(&mut work_loan,|native|{native.begin_effect_settlement(&mut settlement,crate::RetirementDemand{copy_bytes:8,depth:1,..Default::default()})?;let progress=crate::RetainedCloneProgress{copied_items:1,copied_bytes:8,..Default::default()};settlement.as_mut().unwrap().record_effect(progress)?;let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.settle_effect(&mut settlement)));assert!(attempt.is_err());let state=settlement.as_ref().unwrap();assert_eq!(state.work_phase(),if panic=="work"{NativeEncodeEffectPostPhase::Started}else{NativeEncodeEffectPostPhase::Completed});assert_eq!(state.physical_phase(),if panic=="physical"{NativeEncodeEffectPostPhase::Started}else{NativeEncodeEffectPostPhase::Waiting});native.resolve_effect_post(&mut settlement,panic=="work",&mut Some(Ok(())))?;native.settle_effect(&mut settlement)?;let receipt=NativeEncodeEffectSettlement::take_receipt(&mut settlement)?;assert_eq!(receipt.progress(),progress);Ok::<_,ValueError>(())})).unwrap();assert_eq!(work_calls.get(),case["workCalls"].as_u64().unwrap());assert_eq!(physical_calls.get(),case["physicalCalls"].as_u64().unwrap());}
}

#[test]
fn original_effect_recovery_rejects_other_issuer_before_callbacks(){
 use crate::native_encoding::{NativeEncodeConstructionIssuer,NativeEncodeConstructionRecipient};use std::cell::Cell;
 struct Physical<'a>{calls:&'a Cell<usize>,panic:bool,grant:crate::RetainedCloneGrant}impl NativeEncodeConstructionRecipient for Physical<'_>{fn submitted(&self)->crate::RetainedCloneProgress{Default::default()}fn grant(&mut self,_:crate::RetirementDemand)->Result<crate::RetainedCloneGrant,ValueError>{Ok(self.grant)}fn accept(&mut self,_:crate::RetainedCloneGrant,_:crate::RetainedCloneProgress)->Result<(),ValueError>{self.calls.set(self.calls.get()+1);if self.panic{panic!("original receipt unwind")};Ok(())}}
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️settlement.json")).unwrap();let grant=crate::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:fixture["copiedBytes"].as_u64().unwrap() as usize,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let calls=Cell::new(0);let wrong_calls=Cell::new(0);let mut physical=Physical{calls:&calls,panic:true,grant};let mut wrong=Physical{calls:&wrong_calls,panic:false,grant};let mut work=Loan(1);let mut work_issuer=NativeEncodeWorkIssuer::new();let mut physical_issuer=NativeEncodeConstructionIssuer::new();let mut wrong_issuer=NativeEncodeConstructionIssuer::new();let mut callback=|_|true;let mut native=NativeEncodeControl::new(0,&mut callback);let mut settlement=None;
 {let mut pl=physical_issuer.loan(&mut physical);let mut wl=work_issuer.loan(&mut work);let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{native.begin_effect_settlement(&mut settlement,crate::RetirementDemand{copy_bytes:8,depth:1,..Default::default()})?;settlement.as_mut().unwrap().record_effect(crate::RetainedCloneProgress{copied_items:1,copied_bytes:8,..Default::default()})?;native.settle_effect(&mut settlement)}))));assert!(result.is_err());}
 let mut response=Some(Err(ValueError::new(ValueRefusalKind::WorkLimit,String::from("original callback response"))));let pointer=response.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr();{let mut pl=wrong_issuer.loan(&mut wrong);let mut wl=work_issuer.loan(&mut work);native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{assert!(native.resolve_effect_post(&mut settlement,false,&mut response).is_err());Ok::<_,ValueError>(())})).unwrap();}assert_eq!(response.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer);close(response.take().unwrap().unwrap_err(),crate::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096});assert_eq!(wrong_calls.get(),0);assert_eq!(calls.get(),1);
 {let mut pl=physical_issuer.loan(&mut physical);let mut wl=work_issuer.loan(&mut work);native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{native.resolve_effect_post(&mut settlement,false,&mut Some(Ok(())))?;native.settle_effect(&mut settlement)?;let _=crate::native_encoding::NativeEncodeEffectSettlement::take_receipt(&mut settlement)?;Ok::<_,ValueError>(())})).unwrap();}assert_eq!(calls.get(),1);
}

#[test]
fn original_effect_quote_and_work_admission_unwind_never_replay(){
 use crate::native_encoding::{NativeEncodeConstructionIssuer,NativeEncodeConstructionRecipient,NativeEncodeEffectPostPhase};use std::cell::Cell;
 struct Work<'a>{calls:&'a Cell<usize>,panic:bool}impl NativeEncodeWorkRecipient for Work<'_>{fn admits(&mut self,_:u64,_:u64)->Result<bool,ValueError>{self.calls.set(self.calls.get()+1);if self.panic{panic!("work admission fixture")};Ok(true)}fn committed(&mut self,_:u64)->Result<(),ValueError>{Ok(())}}
 struct Physical<'a>{calls:&'a Cell<usize>,panic:bool,grant:crate::RetainedCloneGrant}impl NativeEncodeConstructionRecipient for Physical<'_>{fn submitted(&self)->crate::RetainedCloneProgress{Default::default()}fn grant(&mut self,_:crate::RetirementDemand)->Result<crate::RetainedCloneGrant,ValueError>{self.calls.set(self.calls.get()+1);if self.panic{panic!("quote fixture")};Ok(self.grant)}fn accept(&mut self,_:crate::RetainedCloneGrant,_:crate::RetainedCloneProgress)->Result<(),ValueError>{Ok(())}}
 let f:serde_json::Value=serde_json::from_str(include_str!("🧫️settlement.json")).unwrap();for case in f["admissionCases"].as_array().unwrap(){let which=case.as_str().unwrap();let q=Cell::new(0);let w=Cell::new(0);let grant=crate::RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut physical=Physical{calls:&q,panic:which=="quote",grant};let mut work=Work{calls:&w,panic:which=="work"};let mut pi=NativeEncodeConstructionIssuer::new();let mut wi=NativeEncodeWorkIssuer::new();let mut pl=pi.loan(&mut physical);let mut wl=wi.loan(&mut work);let mut callback=|_|true;let mut native=NativeEncodeControl::new(0,&mut callback);let mut settlement=None;
 native.with_construction_recipient(&mut pl,|native|native.with_work_recipient(&mut wl,|native|{let attempt=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.begin_effect_settlement(&mut settlement,crate::RetirementDemand{copy_bytes:8,depth:1,..Default::default()})));assert!(attempt.is_err());if which=="quote"{assert_eq!(settlement.as_ref().unwrap().quote_phase(),NativeEncodeEffectPostPhase::Started);native.resolve_effect_quote(&mut settlement,&mut Some(Ok(grant)))?;native.resume_effect_admission(&mut settlement)?;}else{assert_eq!(settlement.as_ref().unwrap().admission_phase(),NativeEncodeEffectPostPhase::Started);native.resolve_effect_admission(&mut settlement,&mut Some(Ok(true)))?;}let _=native.cancel_effect_settlement(&mut settlement)?;Ok::<_,ValueError>(())})).unwrap();assert_eq!(q.get(),1);assert_eq!(w.get(),1);assert!(settlement.is_none());}
}

